// === Tab: mySketch ===
let num = 50; // let of rows and columns
let size = 10; // let of the dots
let speed = 0.1; // let of movement
let blurStrength = 20; // let of blur

let bgColor = color(0); // let color
let fg1 = color(255, 255, 255); // let color 1
let fg2 = color(200, 200, 200); // let color 2

let t = 0; // let variable
let aa = new Array(8); 
let bb = new Array(8); 
let transition = 1;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
  frameRate(25);
  initializeArrays();
}

function mouseClicked() {
  resetArrays();
}

function initializeArrays() {
  for (i = 0; i < aa.length; i++) {
    aa[i] = random(-5, 5);
    bb[i] = random(-5, 5);
  }
}

function resetArrays() {
  for (i = 0; i < aa.length; i++) {
    aa[i] = random(-5, 5);
    bb[i] = random(-5, 5);
  }
  transition = 1;
}

function draw() {
  t += 0.01; // let time
  background(bgColor); // let background let transition *= (1 - speed); // let effect

  for (v = 0; v < num; v++) {
    for (u = 0; u < num; u++) {
      let h = 50 * sin((aa[0] * u - aa[1] * v) / num + 4.2 * aa[4] * t + aa[6])
                 * cos((aa[2] * v + aa[3] * u) / num + aa[5] * t + aa[7]);
      let h2 = 50 * sin((bb[0] * u - bb[1] * v) / num + 4.2 * bb[4] * t + bb[6])
                  * cos((bb[2] * v + bb[3] * u) / num + bb[5] * t + bb[7]);
      h = lerp(h, h2, transition);

      let x = map(u, 0, num, 0, width);
      let y = map(v, 0, num, 0, height);

      let blur = (1 - (h / 50)) * blurStrength;

      fill(lerpColor(fg1, fg2, constrain(map(blur, -blurStrength / 3, blurStrength / 2, 0, 1), 0, 1)),
           min(size * 255 / max(sq(blur / 2) * 2, 1), 128));

      ellipse(x, y, max(abs(blur), size), max(abs(blur), size)); // let wave dots
    }
  }
}

